19	package org.apache.pinot.plugin.inputformat.avro;
20	
21	import com.fasterxml.jackson.databind.node.ArrayNode;
22	import com.fasterxml.jackson.databind.node.ObjectNode;
23	import java.util.HashMap;
24	import java.util.List;
25	import java.util.Map;
26	import org.apache.avro.Conversion;
27	import org.apache.avro.Conversions;
28	import org.apache.avro.LogicalType;
29	import org.apache.avro.LogicalTypes;
30	import org.apache.avro.Schema;
31	import org.apache.avro.data.TimeConversions;
32	import org.apache.pinot.spi.data.FieldSpec;
33	import org.apache.pinot.spi.data.FieldSpec.DataType;
34	import org.apache.pinot.spi.utils.JsonUtils;
35	
36	
37	public class AvroSchemaUtil {
38	  /*
39	   * These constants are copied from org.apache.avro.LogicalTypes
40	   */
41	  private static final String DECIMAL = "decimal";
42	  private static final String UUID = "uuid";
43	  private static final String DATE = "date";
44	  private static final String TIME_MILLIS = "time-millis";
45	  private static final String TIME_MICROS = "time-micros";
46	  private static final String TIMESTAMP_MILLIS = "timestamp-millis";
47	  private static final String TIMESTAMP_MICROS = "timestamp-micros";
48	  private static final Map<String, Conversion<?>> CONVERSION_MAP = new HashMap<>();
49	
50	  static {
51	    CONVERSION_MAP.put(DECIMAL, new Conversions.DecimalConversion());
52	    CONVERSION_MAP.put(UUID, new Conversions.UUIDConversion());
53	    CONVERSION_MAP.put(DATE, new TimeConversions.DateConversion());
54	    CONVERSION_MAP.put(TIME_MILLIS, new TimeConversions.TimeMillisConversion());
55	    CONVERSION_MAP.put(TIME_MICROS, new TimeConversions.TimeMicrosConversion());
56	    CONVERSION_MAP.put(TIMESTAMP_MILLIS, new TimeConversions.TimestampMillisConversion());
57	    CONVERSION_MAP.put(TIMESTAMP_MICROS, new TimeConversions.TimestampMicrosConversion());
58	  }
59	
60	  private AvroSchemaUtil() {
61	  }
62	
63	  public static Conversion<?> findConversionFor(String typeName) {
64	    return CONVERSION_MAP.get(typeName);
65	  }
66	
67	  /**
68	   * Returns the data type stored in Pinot that is associated with the given Avro type.
69	   */
70	  public static DataType valueOf(Schema.Type avroType) {
71	    switch (avroType) {
72	      case INT:
73	        return DataType.INT;
74	      case LONG:
75	        return DataType.LONG;
76	      case FLOAT:
77	        return DataType.FLOAT;
78	      case DOUBLE:
79	        return DataType.DOUBLE;
80	      case BOOLEAN:
81	        return DataType.BOOLEAN;
82	      case STRING:
83	      case ENUM:
84	        return DataType.STRING;
85	      case BYTES:
86	      case FIXED:
87	        return DataType.BYTES;
88	      case MAP:
89	      case ARRAY:
90	      case RECORD:
91	      case UNION:
92	        return DataType.JSON;
93	      default:
94	        throw new UnsupportedOperationException("Unsupported Avro type: " + avroType);
95	    }
96	  }
97	
98	  /**
99	   * @return if the given avro type is a primitive type.
100	   */
101	  public static boolean isPrimitiveType(Schema.Type avroType) {
102	    switch (avroType) {
103	      case INT:
104	      case LONG:
105	      case FLOAT:
106	      case DOUBLE:
107	      case BOOLEAN:
108	      case STRING:
109	      case ENUM:
110	        return true;
111	      default:
112	        return false;
113	    }
114	  }
115	
116	  public static ObjectNode toAvroSchemaJsonObject(FieldSpec fieldSpec) {
117	    ObjectNode jsonSchema = JsonUtils.newObjectNode();
118	    jsonSchema.put("name", fieldSpec.getName());
119	    switch (fieldSpec.getDataType().getStoredType()) {
120	      case INT:
121	        jsonSchema.set("type", convertStringsToJsonArray("null", "int"));
122	        return jsonSchema;
123	      case LONG:
124	        jsonSchema.set("type", convertStringsToJsonArray("null", "long"));
125	        return jsonSchema;
126	      case FLOAT:
127	        jsonSchema.set("type", convertStringsToJsonArray("null", "float"));
128	        return jsonSchema;
129	      case DOUBLE:
130	        jsonSchema.set("type", convertStringsToJsonArray("null", "double"));
131	        return jsonSchema;
132	      case STRING:
133	      case JSON:
134	        jsonSchema.set("type", convertStringsToJsonArray("null", "string"));
135	        return jsonSchema;
136	      case BYTES:
137	        jsonSchema.set("type", convertStringsToJsonArray("null", "bytes"));
138	        return jsonSchema;
139	      default:
140	        throw new UnsupportedOperationException();
141	    }
142	  }
143	
144	  private static ArrayNode convertStringsToJsonArray(String... strings) {
145	    ArrayNode jsonArray = JsonUtils.newArrayNode();
146	    for (String string : strings) {
147	      jsonArray.add(string);
148	    }
149	    return jsonArray;
150	  }
151	
152	  /**
153	   * Applies the logical type conversion to the given Avro record field. If there isn't a logical
154	   * type for the value then the value is returned unchanged. If there is a logical type associated
155	   * to the field but no Avro conversion is known for the type then the value is returned unchanged.
156	   *
157	   * @param field Avro field spec
158	   * @param value Value of the field
159	   * @return Converted value as per the logical type in the spec, or the unchanged value if a
160	   *     logical type or conversion can't be found.
161	   */
162	  public static Object applyLogicalType(Schema.Field field, Object value) {
163	    if (field == null || field.schema() == null) {
164	      return value;
165	    }
166	    // Choose the non-null schema when the field schema is represented as union schema. Only then, the avro library
167	    // is able to determine the correct logical type for the field.
168	    Schema fieldSchema = field.schema();
169	    if (fieldSchema.isUnion()) {
170	      List<Schema> fieldSchemas = fieldSchema.getTypes();
171	      for (Schema curSchema: fieldSchemas) {
172	        if (curSchema.getLogicalType() != null) {
173	          fieldSchema = curSchema;
174	          break;
175	        }
176	      }
177	    }
178	    LogicalType logicalType = LogicalTypes.fromSchemaIgnoreInvalid(fieldSchema);
179	    if (logicalType == null) {
180	      return value;
181	    }
182	    Conversion<?> conversion = AvroSchemaUtil.findConversionFor(logicalType.getName());
183	    if (conversion == null) {
184	      return value;
185	    }
186	    return Conversions.convertToLogicalType(value, fieldSchema, logicalType, conversion);
187	  }
188	}
