30	public class AvroSchemaUtilTest {
31	
32	  @Test
33	  public void testApplyLogicalTypeReturnsSameValueWhenFieldIsNull() {
34	    String value = "d7738003-1472-4f63-b0f1-b5e69c8b93e9";
35	
36	    Object result = AvroSchemaUtil.applyLogicalType(null, value);
37	
38	    Assert.assertTrue(result instanceof String);
39	    Assert.assertSame(value, result);
40	  }
41	
42	  @Test
43	  public void testApplyLogicalTypeReturnsSameValueWhenNotUsingLogicalType() {
44	    String value = "abc";
45	    String schemaString =
46	        new StringBuilder().append("{").append("  \"type\": \"record\",").append("  \"name\": \"test\",")
47	            .append("  \"fields\": [{").append("    \"name\": \"column1\",").append("    \"type\": \"string\"")
48	            .append("  }]").append("}").toString();
49	    Schema schema = new Schema.Parser().parse(schemaString);
50	
51	    Object result = AvroSchemaUtil.applyLogicalType(schema.getField("column1"), value);
52	
53	    Assert.assertSame(value, result);
54	  }
55	
56	  @Test
57	  public void testApplyLogicalTypeReturnsSameValueWhenNotConversionForLogicalTypeIsKnown() {
58	    String value = "abc";
59	    String schemaString =
60	        new StringBuilder().append("{").append("  \"type\": \"record\",").append("  \"name\": \"test\",")
61	            .append("  \"fields\": [{").append("    \"name\": \"column1\",").append("    \"type\": {")
62	            .append("      \"type\": \"bytes\",").append("      \"logicalType\": \"custom-type\"").append("    }")
63	            .append("  }]").append("}").toString();
64	    Schema schema = new Schema.Parser().parse(schemaString);
65	
66	    Object result = AvroSchemaUtil.applyLogicalType(schema.getField("column1"), value);
67	
68	    Assert.assertSame(value, result);
69	  }
70	
71	  @Test
72	  public void testApplyLogicalTypeReturnsConvertedValueWhenConversionForLogicalTypeIsKnown() {
73	    String value = "d7738003-1472-4f63-b0f1-b5e69c8b93e9";
74	    String schemaString =
75	        new StringBuilder().append("{").append("  \"type\": \"record\",").append("  \"name\": \"test\",")
76	            .append("  \"fields\": [{").append("    \"name\": \"column1\",").append("    \"type\": {")
77	            .append("      \"type\": \"string\",").append("      \"logicalType\": \"uuid\"").append("    }")
78	            .append("  }]").append("}").toString();
79	    Schema schema = new Schema.Parser().parse(schemaString);
80	
81	    Object result = AvroSchemaUtil.applyLogicalType(schema.getField("column1"), value);
82	
83	    Assert.assertTrue(result instanceof UUID);
84	    Assert.assertEquals(UUID.fromString(value), result);
85	  }
