  private static Object convertElement(Schema schema, Object value) {
    if (value == null) {
      return null;
    }
    Schema effectiveSchema = resolveSchema(schema);
    LogicalType logicalType = LogicalTypes.fromSchemaIgnoreInvalid(effectiveSchema);
    if (logicalType != null) {
